create table if not exists app.analytics_sessions (id uuid primary key default gen_random_uuid(), owner_id uuid references app.profiles(id) on delete cascade, pseudonym text not null, consent text not null, started_at timestamptz not null default now(), expires_at timestamptz not null);
create table if not exists app.analytics_events (id uuid primary key default gen_random_uuid(), session_id uuid references app.analytics_sessions(id) on delete cascade, owner_id uuid references app.profiles(id) on delete cascade, event_name text not null, properties jsonb not null default '{}', occurred_at timestamptz not null default now(), schema_version text not null default 'analytics.v1', unique (id, event_name));
create table if not exists app.analytics_daily_metrics (day date not null, metric_name text not null, value numeric not null, calculation_version text not null, created_at timestamptz not null default now(), primary key (day, metric_name, calculation_version));
alter table app.analytics_sessions enable row level security; alter table app.analytics_events enable row level security; alter table app.analytics_daily_metrics enable row level security;
create policy analytics_session_owner on app.analytics_sessions for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy analytics_event_owner on app.analytics_events for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
